#include <stdint.h>
#include <stddef.h>
int read_le16(const uint8_t *buf, size_t len, size_t offset, uint16_t *out) { if(offset > len || len-offset < 2) return 0; *out=(uint16_t)((uint16_t)buf[offset] | ((uint16_t)buf[offset+1]<<8)); return 1; }
